#!/usr/bin/env bash
# Held-out timelines, experiment 03 camera 01 of each group. Resumable.
cd /e/Coding/Projects/fyp
P=/c/Users/abi/miniconda3/envs/fyp-local/python.exe
[ -f outputs/experiments/06_full_pipeline/timelines/logistic_regression/overview.png ] || { echo "=== 06_full_pipeline logistic_regression $(date +%H:%M)"; $P -m scripts.reporting.plot_results --config docs/experiments/06_full_pipeline_and_labels.json --sessions experiment_03/context_cam_01 --out outputs/experiments/06_full_pipeline/timelines/logistic_regression; }
[ -f outputs/experiments/06_full_pipeline/timelines/random_forest/overview.png ] || { echo "=== 06_full_pipeline random_forest $(date +%H:%M)"; $P -m scripts.reporting.plot_results --config docs/experiments/06_full_pipeline_and_labels.json --set expert.name=random_forest 'expert.params={"n_estimators": 200, "max_depth": 6, "min_samples_leaf": 20, "n_jobs": 4}' --sessions experiment_03/context_cam_01 --out outputs/experiments/06_full_pipeline/timelines/random_forest; }
[ -f outputs/experiments/06_full_pipeline/timelines/knn/overview.png ] || { echo "=== 06_full_pipeline knn $(date +%H:%M)"; $P -m scripts.reporting.plot_results --config docs/experiments/06_full_pipeline_and_labels.json --set expert.name=knn 'expert.params={"n_neighbors": 25, "n_jobs": 4}' --sessions experiment_03/context_cam_01 --out outputs/experiments/06_full_pipeline/timelines/knn; }
[ -f outputs/experiments/08_pca/timelines/logistic_regression/overview.png ] || { echo "=== 08_pca logistic_regression $(date +%H:%M)"; $P -m scripts.reporting.plot_results --config docs/experiments/08_pca.json --set engagement.late_context=false --sessions experiment_03/context_cam_01 --out outputs/experiments/08_pca/timelines/logistic_regression; }
[ -f outputs/experiments/08_pca/timelines/random_forest/overview.png ] || { echo "=== 08_pca random_forest $(date +%H:%M)"; $P -m scripts.reporting.plot_results --config docs/experiments/08_pca.json --set expert.name=random_forest 'expert.params={"n_estimators": 200, "max_depth": 6, "min_samples_leaf": 20, "n_jobs": 4}' engagement.late_context=false expert.pca=27 --sessions experiment_03/context_cam_01 --out outputs/experiments/08_pca/timelines/random_forest; }
[ -f outputs/experiments/08_pca/timelines/knn_k500/overview.png ] || { echo "=== 08_pca knn_k500 $(date +%H:%M)"; $P -m scripts.reporting.plot_results --config docs/experiments/08_pca.json --set expert.name=knn 'expert.params={"n_neighbors": 500, "n_jobs": 4}' engagement.late_context=false expert.pca=0.9 --sessions experiment_03/context_cam_01 --out outputs/experiments/08_pca/timelines/knn_k500; }
[ -f outputs/experiments/08_pca/timelines/knn_k5/overview.png ] || { echo "=== 08_pca knn_k5 $(date +%H:%M)"; $P -m scripts.reporting.plot_results --config docs/experiments/08_pca.json --set expert.name=knn 'expert.params={"n_neighbors": 5, "n_jobs": 4}' engagement.late_context=false expert.pca=20 --sessions experiment_03/context_cam_01 --out outputs/experiments/08_pca/timelines/knn_k5; }
echo "=== done $(date +%H:%M)"
